/*
 * Sidebar `top` clamp.
 *
 * The mint theme's footer/sidebar scroll script sets inline
 * `top = headerOffset - (sidebarContentHeight - footerTop)` on #sidebar to
 * slide it up as the footer scrolls into view. On short pages the footer
 * is visible immediately and our sidebar content is thousands of pixels
 * tall, so it writes an absurd offset like `top:-1729px` (normal is
 * ~100px) and the top of the menu becomes unreachable.
 *
 * #sidebar is re-created on every SPA navigation, so the observer watches
 * the document subtree instead of one node — any style write on any
 * current or future #sidebar gets clamped to the navbar's bottom edge.
 */
(function () {
  function clamp(sidebar) {
    var navbar = document.getElementById("navbar");
    if (!sidebar || !navbar) return;
    var minTop = navbar.getBoundingClientRect().bottom;
    var top = parseFloat(sidebar.style.top);
    if (!isNaN(top) && top < minTop - 1) {
      sidebar.style.top = minTop + "px";
    }
  }

  new MutationObserver(function (muts) {
    for (var i = 0; i < muts.length; i++) {
      var t = muts[i].target;
      if (t && t.id === "sidebar") clamp(t);
    }
  }).observe(document.documentElement, {
    attributes: true,
    attributeFilter: ["style"],
    subtree: true,
  });

  // Also fix whatever value is already there at load.
  var s = document.getElementById("sidebar");
  if (s) clamp(s);
})();

/*
 * Language switcher: preserve api-reference path.
 *
 * Openapi-generated pages don't get proper sibling mapping across languages
 * on Mintlify cloud — clicking the language switcher on /cn/api-reference/xxx
 * falls back to /{targetLang}/introduction. Every language uses the same
 * operationId slug (from x-mint.href in the specs), so a plain URL rewrite
 * always works.
 *
 * The switcher items are `<div role="menuitem">` (not anchors) and clicks are
 * routed through Mintlify's own JS handler. We intercept the click in the
 * capture phase, and when the current URL is an api-reference page we
 * navigate to the same operationId under the picked language, stopping the
 * event so Mintlify's default (jump to /introduction) doesn't run.
 */
(function () {
  var LANG_BY_LABEL = {
    "English": "en",
    "简体中文": "cn",
    "繁體中文": "zh-Hant",
  };

  function currentApiRefSlug() {
    var m = location.pathname.match(/^\/(?:en|cn|zh-Hant|zh-hant)\/api-reference\/([^\/?#]+)$/i);
    return m ? m[1] : null;
  }

  document.addEventListener(
    "click",
    function (e) {
      var t = e.target;
      if (!t || !t.closest) return;
      var item = t.closest('[role="menuitem"][data-component-part="localization-select-item"]');
      if (!item) return;
      var lang = LANG_BY_LABEL[item.textContent.trim()];
      if (!lang) return;
      var slug = currentApiRefSlug();
      if (!slug) return;
      e.preventDefault();
      e.stopImmediatePropagation();
      location.href = "/" + lang + "/api-reference/" + slug;
    },
    true
  );
})();
